-- redemption: A customer's redemption of points for a catalogue item or statement credit
CREATE TABLE redemption (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  points_account_id            uuid NOT NULL REFERENCES points_account(id),
  reward_catalog_item_id       uuid NOT NULL REFERENCES reward_catalog_item(id),
  quantity                     integer NOT NULL DEFAULT 1,
  points_spent                 bigint NOT NULL,
  cash_value                   numeric(28,8),
  currency                     char(3),
  status                       varchar(40) NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED', 'PROCESSING', 'FULFILLED', 'FAILED', 'CANCELLED', 'REVERSED')),
